return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ne_NP','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:34+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'%2$s ब्लक ट्यागमा "%1$s" विशेषता हटाइयो, किनभने ब्लकले त्यो ID भएको कुनै फिल्ड घोषणा गरेको छैन। फिल्ड घोषणा गर्नुहोस्, वा मूल तत्वमा राख्न यसलाई data-, aria- वा html- विशेषताको रूपमा लेख्नुहोस्।','This storage key is not declared by the block or its extensions.'=>'यो भण्डारण कुञ्जी ब्लक वा यसको विस्तारहरूले घोषणा गरेको छैन।','This top-level key is not an attribute of the block, so it is ignored.'=>'यो शीर्ष-स्तरीय कुञ्जी ब्लकको एट्रिब्युट होइन, त्यसैले यसलाई बेवास्ता गरिन्छ।','This key is only read inside the blockstudio object, which is missing.'=>'यो कुञ्जी blockstudio वस्तुभित्र मात्र पढिन्छ, जुन अनुपस्थित छ।','This value is not among the field options.'=>'यो मान फिल्डका विकल्पहरूमा छैन।','This value has an unsupported shape for the field.'=>'यो मानको आकार फिल्डका लागि समर्थित छैन।','This repeater has fewer rows than its minimum.'=>'यो रिपिटरमा न्यूनतमभन्दा कम पङ्क्तिहरू छन्।','This repeater has more rows than its maximum.'=>'यो रिपिटरमा अधिकतमभन्दा बढी पङ्क्तिहरू छन्।','This storage key has conflicting field definitions.'=>'यो भण्डारण कुञ्जीका फिल्ड परिभाषाहरूमा द्वन्द्व छ।','The nested field value overrides this top-level value.'=>'नेस्टेड फिल्डको मानले यो शीर्ष-स्तरीय मानलाई अधिलेखन गर्छ।','Extension bindings read this value only from blockstudio.attributes.'=>'विस्तार बाइन्डिङहरूले यो मान blockstudio.attributes बाट मात्र पढ्छन्।','Blockstudio field values must be stored in an object.'=>'Blockstudio का फिल्ड मानहरू वस्तुमा भण्डारण हुनुपर्छ।','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio ले आफ्नो ब्लक क्यास तयार